/** سلسلة الحلول المرافقة لتجميعية بكالوريا معينة */
export function bacSolutionChainOf(compilationId: string): InteractiveChain | undefined {
  return BAC_SOLUTION_CHAINS.find((c) => c.bacSolutionFor === compilationId);
}

/** إحصائيات الحلول النموذجية للبكالوريا */
export const BAC_SOLUTION_STATS = {
  total: BAC_SOLUTION_CHAINS.length,
  totalExercises: BAC_SOLUTION_CHAINS.reduce((sum, c) => sum + c.exercises.length, 0),
};
